    private void OnSelectEquipmentGroupAsync(EquipmentGroupDto? dto)
    {
        if (dto != null)
        {
            model.EquipmentGroup = dto;

            model.EquipmentGroupId = (int)dto.Id!;

            // Populate fields from selected equipment group
            model.AcceptanceCriteria = dto.AcceptanceCriteria;
            model.Recommendations = dto.Recommendations;
            model.Maintenance = dto.Maintenance;
