    private Task ValidatingMeasurementQuantity(ValidatorEventArgs e, CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();

        try
        {
            short? value = null;
            if(e.Value is not null)
            {
                value = Convert.ToInt16(e.Value);
                value = (value > 0 ? value : null);
            }

            RequiredAttribute? requiredAttr = AttributesHelper.GetRequiredAttribute<EquipmentDto>(x => x.MeasurementQuantityId);
            requiredAttr?.Validate(value, new ValidationContext(model));

            e.Status = ValidationStatus.Success;
            e.ErrorText = "";
        }
        catch(ValidationException ex)
        {
            e.Status = ValidationStatus.Error;
            e.ErrorText = ex.ValidationResult.ErrorMessage;
        }
        catch(Exception ex)
        {
            ErrorState.SetError(ex);
        }

        return Task.CompletedTask;
    }
